window.LIBRARY=[{"id":"ronpyo-points","group":"論理・表現 第11〜13章（12月期末）","title":"論表 文法ルール（第11〜13章）","subject":"論理・表現","order":1,"version":3,"cards":[{"id":"c01","category":"〜ほど…ない","front":"「この本はあの本ほどおもしろくない。」\n英語にすると？","options":["This book is not as interesting as that one.","This book is not as more interesting as that one.","This book is not interesting as that one.","This book is not as interesting than that one."],"answer":0,"back":"答え：This book is not as interesting as that one.\nコツ：「〜ほど…ない」は not as ＿ as。2つ目も as（than にしない）\n（本冊376）"},{"id":"c02","category":"〜倍","front":"「私の部屋は弟の部屋の3倍広い。」\n英語にすると？","options":["My room is three times as larger as my brother's.","My room is as large three times as my brother's.","My room is three times as large as my brother's.","My room is three times as large than my brother's."],"answer":2,"back":"答え：My room is three times as large as my brother's.\nコツ：「3倍」は three times as ＿ as。2倍は twice、半分は half\n（本冊378〜381）"},{"id":"c03","category":"〜倍（大きさ・重さで言う）","front":"「この箱はあの箱の半分の大きさだ。」\nsize を使って英語にすると？","options":["This box is half the size of that one.","This box is the half size of that one.","This box is half the size than that one.","This box is half as size as that one."],"answer":0,"back":"答え：This box is half the size of that one.\nコツ：「半分の大きさ」は half the size of。重さなら the weight of\n（本冊382〜383）"},{"id":"c04","category":"同じだけ（お金・数）","front":"「私は兄と同じだけお金を持っている。」\n英語にすると？","options":["I have as many money as my brother.","I have as money much as my brother.","I have as much money than my brother.","I have as much money as my brother."],"answer":3,"back":"答え：I have as much money as my brother.\nコツ：お金は数えないので much。much money はくっつけて as と as ではさむ\n（本冊377）"},{"id":"c05","category":"できるだけ","front":"「できるだけ早く返事をください。」\npossible を使って英語にすると？","options":["Please reply as sooner as possible.","Please reply as soon than possible.","Please reply as soon as possible.","Please reply the soonest as possible."],"answer":2,"back":"答え：Please reply as soon as possible.\nコツ：「できるだけ〜」は as ＿ as possible。-er の形にしない\n（本冊384〜385）"},{"id":"c06","category":"〜というよりむしろ","front":"He is not so much a teacher as a friend.\nどういう意味？","options":["彼は友だちというより、むしろ先生だ。","彼は先生というより、むしろ友だちだ。","彼は先生ほど多くの友だちがいない。","彼は先生でもないし、友だちでもない。"],"answer":1,"back":"答え：彼は先生というより、むしろ友だちだ。\nコツ：not so much ＿ as 〜 は「＿というより〜」。後ろの方が本当\n（本冊386）"},{"id":"c07","category":"〜さえしない","front":"She left without so much as saying goodbye.\nどういう意味？","options":["彼女はたくさんさようならを言って去った。","彼女はさようならさえ言わずに去った。","彼女はさようならを言ってから去った。","彼女はさようならを言わずに、ここに残った。"],"answer":1,"back":"答え：彼女はさようならさえ言わずに去った。\nコツ：without so much as ＿ は「＿さえしないで」\n（本冊387〜388）"},{"id":"c08","category":"だれにも負けない","front":"He is as great a singer as ever lived.\nどういう意味？","options":["彼は昔、すごい歌手として生きていた。","彼はずっと長生きしている歌手だ。","彼は昔の歌手と同じくらい、ふつうの歌手だ。","彼は今までにいないほどすごい歌手だ。"],"answer":3,"back":"答え：彼は今までにいないほどすごい歌手だ。\nコツ：as ＿ as ever lived は「今までにいないほど＿」\n（本冊389〜390）"},{"id":"c09","category":"〜も（多い）","front":"「そのコンサートには5万人もの人が来た。」\n英語にすると？","options":["As many as 50,000 people came to the concert.","As much as 50,000 people came to the concert.","As many 50,000 people as came to the concert.","As more as 50,000 people came to the concert."],"answer":0,"back":"答え：As many as 50,000 people came to the concert.\nコツ：人の数が多くて「〜も」は as many as。お金・時間なら as much as\n（本冊391）"},{"id":"c10","category":"たった〜（少ない）","front":"「このシャツはたった4ドルだった。」\nas を使って英語にすると？","options":["This shirt cost as less as four dollars.","This shirt cost as little as four dollars.","This shirt cost as little than four dollars.","This shirt cost as many as four dollars."],"answer":1,"back":"答え：This shirt cost as little as four dollars.\nコツ：お金の「たった」は as little as。as many as は「〜も（多い）」で反対\n（本冊392）"},{"id":"c11","category":"早くも〜に","front":"Snow fell as early as October.\nどういう意味？","options":["10月より前に、一度だけ雪が降った。","10月になってもまだ雪が降った。","早くも10月に雪が降った。","10月のはじめにだけ雪が降った。"],"answer":2,"back":"答え：早くも10月に雪が降った。\nコツ：as early as ＿ は「早くも＿に」。as late as ＿ は「＿になってもまだ」\n（本冊393）"},{"id":"c12","category":"ずっと〜（強める）","front":"「今日は昨日よりずっと寒い。」\n英語にすると？","options":["Today is very colder than yesterday.","Today is much cold than yesterday.","Today is much more colder than yesterday.","Today is much colder than yesterday."],"answer":3,"back":"答え：Today is much colder than yesterday.\nコツ：「ずっと」は much を colder の前に。very は使えない\n（本冊394）"},{"id":"c13","category":"〜ほど…ない（less）","front":"「この車はあの車ほど高くない。」\nless を使って英語にすると？","options":["This car is less expensive as that one.","This car is less expensive than that one.","This car is less expensiver than that one.","This car is expensive less than that one."],"answer":1,"back":"答え：This car is less expensive than that one.\nコツ：not as ＿ as は less ＿ than と言いかえられる\n（本冊395）"},{"id":"c14","category":"〜というよりむしろ","front":"「彼は怒っているというより、むしろ悲しんでいる。」\n英語にすると？","options":["He is sadder than angry.","He is more sadder than angry.","He is more angry than sad.","He is more sad than angry."],"answer":3,"back":"答え：He is more sad than angry.\nコツ：同じ人の2つの様子をくらべるときは more ＿ than。sadder にしない\n（本冊396）"},{"id":"c15","category":"〜倍","front":"「この橋はあの橋の3倍長い。」\nlonger を使って英語にすると？","options":["This bridge is three times longer than that one.","This bridge is longer three times than that one.","This bridge is three times longer as that one.","This bridge is three times long than that one."],"answer":0,"back":"答え：This bridge is three times longer than that one.\nコツ：three times を longer の前に置くだけ\n（本冊397）"},{"id":"c16","category":"2つのうちの〜なほう","front":"「2人のうちで、ケンのほうが背が高い。」\n英語にすると？","options":["Ken is taller of the two.","Ken is the taller of the two.","Ken is the taller than the two.","Ken is the tall of the two."],"answer":1,"back":"答え：Ken is the taller of the two.\nコツ：「2人のうちで〜なほう」は the ＿er of the two。the を忘れない\n（本冊398）"},{"id":"c17","category":"〜すればするほど","front":"「たくさん練習すればするほど、うまくなる。」\n英語にすると？","options":["The more you practice, the good you get.","The more you practice, the better you get.","More you practice, better you get.","The more you practice, you get the better."],"answer":1,"back":"答え：The more you practice, the better you get.\nコツ：「〜すればするほど」は The ＿er …, the ＿er …。the を2回\n（本冊399〜400）"},{"id":"c18","category":"〜なのでいっそう","front":"I like him all the better for his honesty.\nどういう意味？","options":["彼は正直だが、私はあまり彼が好きではない。","私は彼の正直さより、ほかの所が好きだ。","彼が正直になれば、もっと好きになるだろう。","彼が正直なので、私はいっそう彼が好きだ。"],"answer":3,"back":"答え：彼が正直なので、私はいっそう彼が好きだ。\nコツ：all the ＿er for 〜 は「〜なので、いっそう＿」\n（本冊401）"},{"id":"c19","category":"〜なのに少しも…ない","front":"He is none the happier for his money.\nどういう意味？","options":["彼はお金がないので、少しも幸せではない。","彼はお金があるので、とても幸せだ。","彼はお金があるのに、少しも幸せではない。","彼はだれよりもお金があって幸せだ。"],"answer":2,"back":"答え：彼はお金があるのに、少しも幸せではない。\nコツ：none the ＿er for 〜 は「〜なのに少しも＿ない」\n（本冊402）"},{"id":"c20","category":"たった〜／〜も","front":"I have no more than 500 yen.\nどういう意味？","options":["私は500円しか持っていない。","私は500円より多く持っている。","私は500円も持っている。","私はもう500円は持っていない。"],"answer":0,"back":"答え：私は500円しか持っていない。\nコツ：no more than ＝「たった」。no less than は「〜も（多い！）」\n（本冊405〜406）"},{"id":"c21","category":"多くても／少なくとも","front":"The trip will cost not more than 3,000 yen.\nどういう意味？","options":["その旅行は、少なくとも3000円はかかる。","その旅行は、3000円よりずっと多くかかる。","その旅行は、もう3000円はかからない。","その旅行は、多くても3000円しかかからない。"],"answer":3,"back":"答え：その旅行は、多くても3000円しかかからない。\nコツ：not more than ＝「多くても」。not less than ＝「少なくとも」"},{"id":"c22","category":"〜でないのと同じ","front":"A bat is no more a bird than a dog is.\nどういう意味？","options":["コウモリが鳥でないのは、犬が鳥でないのと同じだ。","コウモリは、犬よりもずっと鳥に近い生き物だ。","コウモリは鳥の仲間だが、犬は鳥ではない。","コウモリも犬も、もう今は鳥ではなくなった。"],"answer":0,"back":"答え：コウモリが鳥でないのは、犬が鳥でないのと同じだ。\nコツ：no more 〜 than … は「…と同じで、まったく〜ではない」\n（本冊407）"},{"id":"c23","category":"〜でないのと同じ","front":"「イルカが魚でないのは、ネコが魚でないのと同じだ。」\nnot と any more を使って英語にすると？","options":["A dolphin is not a fish any more as a cat is.","A dolphin is not a fish more any than a cat is.","A dolphin is not a fish any more than a cat are.","A dolphin is not a fish any more than a cat is."],"answer":3,"back":"答え：A dolphin is not a fish any more than a cat is.\nコツ：no more を not … any more に分けて置くだけ\n（本冊408）"},{"id":"c24","category":"〜に負けないくらい","front":"She is no less kind than her mother is.\nどういう意味？","options":["彼女はお母さんほどやさしくない。","彼女はお母さんに負けないくらいやさしい。","彼女はやさしいが、お母さんはやさしくない。","彼女はもうお母さんにやさしくない。"],"answer":1,"back":"答え：彼女はお母さんに負けないくらいやさしい。\nコツ：no less ＿ than 〜 は「〜に負けないくらい＿だ」\n（本冊409）"},{"id":"c25","category":"決まった言い方","front":"He knows better than to play games before a test.\nどういう意味？","options":["彼はテストの前にゲームをするのがいちばん好きだ。","彼はテストの前にゲームをしたほうがいいと知っている。","彼はテストの前にゲームをするほどばかではない。","彼はテストよりもゲームのほうがずっと得意だ。"],"answer":2,"back":"答え：彼はテストの前にゲームをするほどばかではない。\nコツ：know better than to ＿ は「＿するほどばかじゃない」\n（本冊410〜411）"},{"id":"c26","category":"まして〜ない","front":"「私はピアノをひけない。まして教えることなんてできない。」\n英語にすると？","options":["I can't play the piano, much more teach it.","I can't play the piano, less much teach it.","I can't play the piano, much less teach it.","I can play the piano, much less teach it."],"answer":2,"back":"答え：I can't play the piano, much less teach it.\nコツ：「まして〜ない」は「〜ない」の文のあとに , much less 〜\n（本冊412）"},{"id":"c27","category":"もう〜ない","front":"「彼はもうここに住んでいない。」\nno longer を使って英語にすると？","options":["He no longer lives here.","He no longer doesn't live here.","He no longer live here.","He lives here no long."],"answer":0,"back":"答え：He no longer lives here.\nコツ：「もう〜ない」は no longer。not はもう入れない\n（本冊413）"},{"id":"c28","category":"than のかわりに to","front":"「このカメラはあのカメラより優れている。」\nsuperior を使って英語にすると？","options":["This camera is superior than that one.","This camera is more superior than that one.","This camera is superior as that one.","This camera is superior to that one."],"answer":3,"back":"答え：This camera is superior to that one.\nコツ：superior（優れた）は than でなく to。inferior・senior・junior も to\n（本冊414・416）"},{"id":"c29","category":"〜より…が好き","front":"「私はコーヒーより紅茶のほうが好きだ。」\nprefer を使って英語にすると？","options":["I prefer tea than coffee.","I prefer coffee to tea.","I prefer tea from coffee.","I prefer tea to coffee."],"answer":3,"back":"答え：I prefer tea to coffee.\nコツ：prefer ＿ to 〜 で「〜より＿が好き」。好きな方が先。than は使わない\n（本冊415）"},{"id":"c30","category":"いちばん（in と of）","front":"「ケンはクラスでいちばん背が高い。」\n英語にすると？","options":["Ken is the tallest of the class.","Ken is the tallest in the class.","Ken is the taller in the class.","Ken is the most tallest in the class."],"answer":1,"back":"答え：Ken is the tallest in the class.\nコツ：クラスなど場所・グループは in。「3人の中で」のような人数なら of\n（本冊417）"},{"id":"c31","category":"断然いちばん","front":"「富士山は日本で断然いちばん高い山だ。」\nby far を使って英語にすると？","options":["Mt. Fuji is the by far highest mountain in Japan.","Mt. Fuji is by far the highest mountain in Japan.","Mt. Fuji is very the highest mountain in Japan.","Mt. Fuji is by far the higher mountain in Japan."],"answer":1,"back":"答え：Mt. Fuji is by far the highest mountain in Japan.\nコツ：「断然いちばん」は by far the ＿est。by far は the の前\n（本冊418〜419）"},{"id":"c32","category":"2番目に〜","front":"「ケンはクラスで2番目に背が高い。」\n英語にすると？","options":["Ken is the second tallest in the class.","Ken is the tallest second in the class.","Ken is second the tallest in the class.","Ken is the second taller in the class."],"answer":0,"back":"答え：Ken is the second tallest in the class.\nコツ：「2番目に〜」は the second ＿est\n（本冊420）"},{"id":"c33","category":"いちばん〜な…の1つ","front":"「彼は日本でいちばん有名な歌手の1人だ。」\n英語にすると？","options":["He is one of the most famous singer in Japan.","He is one of most famous singers in Japan.","He is one of the famousest singers in Japan.","He is one of the most famous singers in Japan."],"answer":3,"back":"答え：He is one of the most famous singers in Japan.\nコツ：「〜の1人」は one of the most ＿ ＿s。最後に s（singers）\n（本冊421）"},{"id":"c34","category":"今までで一番","front":"「こんなにいい映画は見たことがない。」\nThis is で始めて英語にすると？","options":["This is the best movie I have ever seen.","This is the best movie I have never seen.","This is the better movie I have ever seen.","This is the best movie I have ever see."],"answer":0,"back":"答え：This is the best movie I have ever seen.\nコツ：「今まで〜した中でいちばん」は the best … I have ever ＿\n（本冊422〜423）"},{"id":"c35","category":"少なくとも／多くても","front":"「少なくとも1日1時間は勉強しなさい。」\n英語にすると？","options":["Study for at most one hour a day.","Study for at little one hour a day.","Study for the least one hour a day.","Study for at least one hour a day."],"answer":3,"back":"答え：Study for at least one hour a day.\nコツ：「少なくとも」は at least。「多くても」は at most\n（本冊424）"},{"id":"c36","category":"ほかのだれも〜ない","front":"「クラスのほかのだれもケンほど背が高くない。」\nNo other で始めて英語にすると？","options":["No other students in the class is as tall as Ken.","No other student in the class is as tall than Ken.","No other student in the class is as tall as Ken.","No other student in the class is not as tall as Ken."],"answer":2,"back":"答え：No other student in the class is as tall as Ken.\nコツ：No other student（s を付けない）。not は入れない\n（本冊425・427）"},{"id":"c37","category":"〜ほど…なものはない","front":"「健康ほど大切なものはない。」\nNothing で始めて英語にすると？","options":["Nothing is as important than health.","Nothing is not as important as health.","Nothing is as important as health.","Nothing is as more important as health."],"answer":2,"back":"答え：Nothing is as important as health.\nコツ：「〜ほど…なものはない」は Nothing is as ＿ as 〜\n（本冊426・428）"},{"id":"c38","category":"ほかのどの〜よりも","front":"「富士山は日本のほかのどの山よりも高い。」\nany other を使って英語にすると？","options":["Mt. Fuji is higher than any other mountains in Japan.","Mt. Fuji is higher than any mountain other in Japan.","Mt. Fuji is high than any other mountain in Japan.","Mt. Fuji is higher than any other mountain in Japan."],"answer":3,"back":"答え：Mt. Fuji is higher than any other mountain in Japan.\nコツ：any other のあとは1つの形（mountain、s を付けない）\n（本冊429〜430）"},{"id":"c39","category":"is・are などの形を合わせる","front":"「トムもケンもサッカーが好きだ。」\nboth を使って英語にすると？","options":["Both Tom and Ken like soccer.","Both Tom and Ken likes soccer.","Both Tom or Ken like soccer.","Tom both and Ken like soccer."],"answer":0,"back":"答え：Both Tom and Ken like soccer.\nコツ：both ＿ and 〜 は「2人」なので like（likes にしない）\n（本冊431）"},{"id":"c40","category":"is・are などの形を合わせる","front":"「ケンか私のどちらかがまちがっている。」\neither を使って英語にすると？","options":["Either Ken or I is wrong.","Either Ken or I are wrong.","Either Ken or I am wrong.","Either Ken and I am wrong."],"answer":2,"back":"答え：Either Ken or I am wrong.\nコツ：am / is / are は or のすぐ後ろ（I）に合わせる → am\n（本冊432〜434）"},{"id":"c41","category":"is・are などの形を合わせる","front":"「生徒たちだけでなく、先生も疲れていた。」\nas well as を使って英語にすると？","options":["The teacher as well as the students were tired.","The teacher as well as the students is tired.","The teacher as well as the students was tired.","The teacher as good as the students was tired."],"answer":2,"back":"答え：The teacher as well as the students was tired.\nコツ：as well as の前（the teacher＝1人）に合わせる → was\n（本冊435）"},{"id":"c42","category":"is・are などの形を合わせる","front":"「そのケーキのほとんどが食べられた。」\nMost of で始めて英語にすると？","options":["Most of the cake were eaten.","Most the cake was eaten.","Most of the cake was eat.","Most of the cake was eaten."],"answer":3,"back":"答え：Most of the cake was eaten.\nコツ：of の後ろ（the cake＝1つ）に合わせる → was。the students なら were\n（本冊436〜438）"},{"id":"c43","category":"is・are などの形を合わせる","front":"「箱の中にりんごが3つある。」\n英語にすると？","options":["There is three apples in the box.","There are three apple in the box.","There are three apples in the box.","Three apples there are in the box."],"answer":2,"back":"答え：There are three apples in the box.\nコツ：There のあとは後ろの物に合わせる。3つなら are\n（本冊439〜440）"},{"id":"c44","category":"is・are などの形を合わせる","front":"「この町の子どもの数は減っている。」\n英語にすると？","options":["The number of children in this town is decreasing.","The number of children in this town are decreasing.","A number of children in this town is decreasing.","The number of child in this town is decreasing."],"answer":0,"back":"答え：The number of children in this town is decreasing.\nコツ：the number of 〜「〜の数」は1つの数なので is\n（本冊441〜442）"},{"id":"c45","category":"is・are などの形を合わせる","front":"「10キロは歩くには遠すぎる。」\n英語にすると？","options":["Ten kilometers is too far to walk.","Ten kilometers are too far to walk.","Ten kilometer is too far to walk.","Ten kilometers is too far to walking."],"answer":0,"back":"答え：Ten kilometers is too far to walk.\nコツ：きょり・お金・時間は1つのまとまりなので is\n（本冊443〜444）"},{"id":"c46","category":"is・are などの形を合わせる","front":"「お金持ちがいつも幸せとはかぎらない。」\nthe rich を使って英語にすると？","options":["The rich is not always happy.","The rich are not always happy.","Rich are not always happy.","The riches are not always happy."],"answer":1,"back":"答え：The rich are not always happy.\nコツ：the rich ＝「お金持ちの人たち」なので are\n（本冊445）"},{"id":"c47","category":"is・are などの形を合わせる","front":"「私には東京に住んでいる友だちが2人いる。」\nwho を使って英語にすると？","options":["I have two friends who lives in Tokyo.","I have two friend who live in Tokyo.","I have two friends who live in Tokyo.","I have two friends who they live in Tokyo."],"answer":2,"back":"答え：I have two friends who live in Tokyo.\nコツ：who のあとは前の two friends に合わせる → live（lives にしない）\n（本冊446）"},{"id":"c48","category":"is・are などの形を合わせる","front":"「その店のケーキの値段は高い。」\n英語にすると？","options":["The price of the cakes at the shop are high.","The price of the cakes at the shop is high.","The prices of the cakes at the shop is high.","The cakes of the price at the shop is high."],"answer":1,"back":"答え：The price of the cakes at the shop is high.\nコツ：中心は price（値段＝1つ）。近くの cakes につられて are にしない\n（本冊447）"},{"id":"c49","category":"聞き方（How＋〜）","front":"「どのくらいよく映画を見に行きますか。」\n英語にすると？","options":["How far do you go to the movies?","How often do you go to the movies?","How long do you go to the movies?","How often you go to the movies?"],"answer":1,"back":"答え：How often do you go to the movies?\nコツ：「何回くらい」は How often。きょりは How far、長さは How long\n（本冊450〜453）"},{"id":"c50","category":"聞き方（How＋〜）","front":"「駅まで歩いてどれくらい時間がかかりますか。」\n英語にすると？","options":["How long does it takes to walk to the station?","How far does it take to walk to the station?","How long does it take to walk to the station?","How long it takes to walk to the station?"],"answer":2,"back":"答え：How long does it take to walk to the station?\nコツ：「時間がかかる」は How long does it take (to 〜)?\n（本冊452）"},{"id":"c51","category":"聞き方（How＋〜）","front":"「この教室には生徒が何人いますか。」\n英語にすると？","options":["How much students are there in this classroom?","How many student are there in this classroom?","How many students are there in this classroom?","How many students there are in this classroom?"],"answer":2,"back":"答え：How many students are there in this classroom?\nコツ：数えられる物は How many ＋ ＿s。お金や量は How much\n（本冊449）"},{"id":"c52","category":"文の中の「どこ・なに」","front":"「彼女がどこに住んでいるのか知りたい。」\n英語にすると？","options":["I want to know where she lives.","I want to know where does she live.","I want to know where she live.","I want to know where lives she."],"answer":0,"back":"答え：I want to know where she lives.\nコツ：文の中では where she lives の順。does は入れない\n（本冊454〜455）"},{"id":"c53","category":"「〜と思う？」の聞き方","front":"「彼はどこにいると思いますか。」\n英語にすると？","options":["Do you think where he is?","Where do you think he is?","Where do you think is he?","Where are you think he is?"],"answer":1,"back":"答え：Where do you think he is?\nコツ：Where を先頭に出して do you think を入れる。後ろは he is の順\n（本冊456〜457）"},{"id":"c54","category":"「〜しないの？」への答え","front":"「Don't you like coffee? ─ うん、好きじゃないよ。」\n「うん、好きじゃない」を英語にすると？","options":["No, I don't.","Yes, I don't.","Yes, I do.","No, I do."],"answer":0,"back":"答え：No, I don't.\nコツ：好きじゃないなら No。日本語の「うん」につられて Yes にしない\n（本冊458）"},{"id":"c55","category":"「〜だよね？」","front":"「今日は寒いよね？」\n英語にすると？","options":["It is cold today, is it?","It is cold today, isn't it?","It is cold today, doesn't it?","It is cold today, isn't today?"],"answer":1,"back":"答え：It is cold today, isn't it?\nコツ：not なしの文には isn't it?。is の文なので doesn't にしない\n（本冊459〜460）"},{"id":"c56","category":"「〜だよね？」","front":"「お昼を食べに行こうよ、ね？」\nLet's で始めて英語にすると？","options":["Let's go for lunch, shall we?","Let's go for lunch, will you?","Let's go for lunch, don't we?","Let's go for lunch, shall us?"],"answer":0,"back":"答え：Let's go for lunch, shall we?\nコツ：Let's 〜 のあとの「ね？」は shall we?\n（本冊461〜462）"},{"id":"c57","category":"決まった聞き方","front":"「どこの出身ですか。」\ncome を使って英語にすると？","options":["Where did you come from?","Where are you come from?","Where do you come from?","Where you come from?"],"answer":2,"back":"答え：Where do you come from?\nコツ：出身はずっと変わらないので do you come。did you come にしない\n（本冊463）"},{"id":"c58","category":"決まった聞き方","front":"What is your new teacher like?\nどういう意味？","options":["新しい先生は何が好きですか。","新しい先生はどんな人ですか。","新しい先生はだれが好きですか。","新しい先生に似ているのはだれですか。"],"answer":1,"back":"答え：新しい先生はどんな人ですか。\nコツ：What is ＿ like? は「＿はどんな感じ？」。like は「好き」ではない\n（本冊464〜465）"},{"id":"c59","category":"決まった聞き方","front":"「この映画をどう思いますか。」\n英語にすると？","options":["How do you think of this movie?","What do you think of this movie?","What do you think this movie?","What are you think of this movie?"],"answer":1,"back":"答え：What do you think of this movie?\nコツ：「どう思う」は What do you think of 〜?。「どう」につられて How にしない\n（本冊466）"},{"id":"c60","category":"決まった聞き方","front":"What has become of the old school?\nどういう意味？","options":["あの古い学校は何になりたいのですか。","何があの古い学校になったのですか。","あの古い学校で何をしたのですか。","あの古い学校はどうなったのですか。"],"answer":3,"back":"答え：あの古い学校はどうなったのですか。\nコツ：What has become of ＿? は「＿はどうなった？」\n（本冊467）"},{"id":"c61","category":"決まった聞き方","front":"「どうして昨日来なかったの？」\nHow come で始めて英語にすると？","options":["How come you didn't come yesterday?","How come did you not come yesterday?","How come didn't you come yesterday?","How come you don't came yesterday?"],"answer":0,"back":"答え：How come you didn't come yesterday?\nコツ：How come のあとはふつうの文の順（you didn't …）\n（本冊468）"},{"id":"c62","category":"決まった聞き方","front":"What did you go to Tokyo for?\nどういう意味？","options":["どうやって東京へ行ったのですか。","だれといっしょに東京へ行ったのですか。","何のために東京へ行ったのですか。","東京で何を買ったのですか。"],"answer":2,"back":"答え：何のために東京へ行ったのですか。\nコツ：What 〜 for? は「何のために〜？」\n（本冊469）"},{"id":"c63","category":"決まった聞き方","front":"Why don't we go swimming?\nどういう意味？","options":["（あなたが）泳ぎに行ったらどう？","私たちは泳ぎに行きたくない。","どうして泳ぎに行ったの？","いっしょに泳ぎに行こうよ。"],"answer":3,"back":"答え：いっしょに泳ぎに行こうよ。\nコツ：Why don't we 〜? は「いっしょに〜しよう」。Why don't you 〜? は「〜したらどう？」\n（本冊470〜471）"},{"id":"c64","category":"決まった聞き方","front":"「散歩に行くのはどう？」\nWhat about を使って英語にすると？","options":["What about go for a walk?","What about going for a walk?","What about to go for a walk?","What about went for a walk?"],"answer":1,"back":"答え：What about going for a walk?\nコツ：What about のあとは ＿ing（going）\n（本冊472）"},{"id":"c65","category":"聞くふりの言い方","front":"Who knows?\nどういう意味？","options":["だれでも知っているよ。","だれかが知っているよ。","あなたは知っているの？","だれにもわからないよ。"],"answer":3,"back":"答え：だれにもわからないよ。\nコツ：「だれが知ってる？」→「だれも知らない」という意味\n（本冊473）"},{"id":"c66","category":"聞くふりの言い方","front":"「今さら泣いてもむだだ。」\nIt is no use を使って英語にすると？","options":["It is no use crying now.","It is no use cry now.","It is not use crying now.","It is no used crying now."],"answer":0,"back":"答え：It is no use crying now.\nコツ：「〜してもむだ」は It is no use ＿ing\n（本冊474）"},{"id":"c67","category":"What と Where の使い分け","front":"「日本の首都はどこですか。」\n英語にすると？","options":["Where is the capital of Japan?","What the capital of Japan is?","What is the capital of Japan?","Where the capital of Japan is?"],"answer":2,"back":"答え：What is the capital of Japan?\nコツ：答えが「東京」という名前なら What。場所を聞くなら Where\n（本冊448）"}]},{"id":"ronpyo-374","group":"論理・表現 第11〜13章（12月期末）","title":"論表 比較の前半（本冊374〜402と同じ文法）","subject":"論理・表現","order":1.5,"version":4,"cards":[{"id":"k374","category":"A 4択","front":"Emi swims as （　） as her older sister.","options":["faster","fast","fastest","more fast"],"answer":1,"back":"答え：fast\n訳：エミはお姉さんと同じくらい速く泳ぐ。\nコツ：as と as ではさまれたら、もとの形（fast）のまま。-er はつけない。\n（本冊374）"},{"id":"k375","category":"A 4択","front":"This river is as clean today as it （　） twenty years ago.","options":["was","is","does","has been"],"answer":0,"back":"答え：was\n訳：この川は今も20年前と同じくらいきれいだ。\nコツ：twenty years ago（20年前）は昔のこと。だから was。\n（本冊375）"},{"id":"k376","type":"order","category":"B 並べ替え","front":"「そのゲームはみんなが言うほどおもしろくなかった。」\nThe game was （　　　）.","words":["not","so","exciting","as","people","said"],"back":"答え：not so exciting as people said（2番目 so／5番目 people）\n訳：そのゲームはみんなが言うほどおもしろくなかった。\nコツ：「～ほど…ない」は not so … as ～。not so のあとに exciting、そのあと as people said。\n（本冊376）"},{"id":"k377","type":"order","category":"B 並べ替え","front":"「私は兄と同じくらいたくさんのマンガを読んだ。」\nI have read （　　　）.","words":["as","many","comics","as","my","brother"],"back":"答え：as many comics as my brother（2番目 many／5番目 my）\n訳：私は兄と同じくらいたくさんのマンガを読んだ。\nコツ：many comics はくっつけたまま、as と as ではさむ。マンガは数えられるので many。\n（本冊377）"},{"id":"k378","category":"A 4択","front":"My dog is （　） as heavy as yours.","options":["two","double times","twice times","twice"],"answer":3,"back":"答え：twice\n訳：私の犬はあなたの犬の2倍重い。\nコツ：「2倍」は twice の1語だけ。as heavy as の前に置く。\n（本冊378）"},{"id":"k379","category":"A 4択","front":"This tower is （　） as tall as that building.","options":["three time","the third times","three times","times three"],"answer":2,"back":"答え：three times\n訳：この塔はあのビルの3倍高い。\nコツ：「3倍」から上は「数 ＋ times」。times には s がつく。\n（本冊379）"},{"id":"k380","type":"order","category":"B 並べ替え","front":"「この池はあの池の3分の1の広さだ。」\nThis pond is （　　　）.","words":["one","third","as","large","as","that","one"],"back":"答え：one third as large as that one（2番目 third／5番目 as）\n訳：この池はあの池の3分の1の広さだ。\nコツ：「3分の1」one third を先に言って、そのあと as large as。\n（本冊380）"},{"id":"k381","type":"order","category":"B 並べ替え","front":"「この新しい車は、古い車の半分のガソリンしか使わない。」\nThis new car uses （　　　）.","words":["half","as","much","gas","as","the","old","one"],"back":"答え：half as much gas as the old one（2番目 as／5番目 as）\n訳：この新しい車は、古い車の半分のガソリンしか使わない。\nコツ：much gas はくっつけたまま。half を先に置いて as much gas as。\n（本冊381）"},{"id":"k382","category":"A 4択","front":"The new library is twice （　） of the old one.","options":["as size","the size","size as","the large"],"answer":1,"back":"答え：the size\n訳：新しい図書館は古い図書館の2倍の大きさだ。\nコツ：後ろに of があるので the size of（～の大きさ）。twice as large as と同じ意味。\n（本冊382）"},{"id":"k383","type":"order","category":"B 並べ替え","front":"「このボートはあの車の10分の1の速さで進む。」\nThis boat moves at （　　　）.","words":["one-tenth","the","speed","of","that","car"],"back":"答え：one-tenth the speed of that car（2番目 the／5番目 that）\n訳：このボートはあの車の10分の1の速さで進む。\nコツ：「10分の1」→「速さ（the speed）」→「～の（of）」。日本語と同じ順番。\n（本冊383）"},{"id":"k384","category":"A 4択","front":"Spend （　） with your friends.","options":["as many time as possible","as time much as possible","as much as possible time","as much time as possible"],"answer":3,"back":"答え：as much time as possible\n訳：友だちとできるだけ多くの時間を過ごしなさい。\nコツ：much time はくっつけたまま as と as ではさむ。時間は数えないので much。\n（本冊384）"},{"id":"k385","category":"A 4択","front":"Speak as loudly as you （　）.","options":["possible","are","can","able"],"answer":2,"back":"答え：can\n訳：できるだけ大きな声で話しなさい。\nコツ：as ～ as you can ＝ できるだけ。you があるので possible ではなく can。\n（本冊385）"},{"id":"k386","type":"write","category":"C 書きかえ","front":"(a) She is a singer rather than an actor.\n(b) She is （ ① ） （ ② ） （ ③ ） an actor （ ④ ） a singer.","answers":[["not"],["so"],["much"],["as"]],"back":"答え：① not ② so ③ much ④ as\n訳：彼女は女優というより、むしろ歌手だ。\nコツ：not so much A as B ＝「A というより B」。本当の方（singer）を最後に言う。\n（本冊386）"},{"id":"k387","category":"A 4択","front":"He did not so much as （　） hello to me.","options":["saying","said","to say","say"],"answer":3,"back":"答え：say\n訳：彼は私にあいさつさえしなかった。\nコツ：did not のあとは、もとの形（say）。so much as がはさまっても同じ。\n（本冊387）"},{"id":"k388","category":"A 4択","front":"She left without so much as （　） goodbye.","options":["saying","say","said","to say"],"answer":0,"back":"答え：saying\n訳：彼女はさようならも言わずに帰った。\nコツ：without（～しないで）のあとは -ing の形。\n（本冊388）"},{"id":"k389","category":"A 4択","front":"He was as great （　） as ever lived.","options":["baseball player","a baseball player","the baseball player","baseball players"],"answer":1,"back":"答え：a baseball player\n訳：彼は今までいた中でも、だれにも負けないすごい野球選手だった。\nコツ：as great のすぐ後ろは「a ＋ 1人」。as great a baseball player の順番。\n（本冊389）"},{"id":"k390","category":"A 4択","front":"This is as exciting a movie as （　） I have ever seen.","options":["all","every","no","any"],"answer":3,"back":"答え：any\n訳：これは私が今まで見たどの映画にも負けないくらいおもしろい。\nコツ：「どの～にも負けない」は as ～ as any。any ＝「どれでも」。\n（本冊390）"},{"id":"k391","category":"A 4択","front":"（　） 10,000 people came to the game, so the stadium was full.","options":["As much as","As little as","As many as","As more as"],"answer":2,"back":"答え：As many as\n訳：その試合には1万人もの人が来たので、スタジアムはいっぱいだった。\nコツ：人は数えられる → many。「～人も！」と多さを言うときは as many as。\n（本冊391）"},{"id":"k392","category":"A 4択","front":"You can buy the pen for as （　） as 100 yen.","options":["few","little","small","less"],"answer":1,"back":"答え：little\n訳：そのペンはたった100円で買える。\nコツ：お金は「量」のなかま → little。「たった～」と少なさを言うときは as little as。\n（本冊392）"},{"id":"k393","category":"A 4択","front":"My father got up as （　） as four in the morning.","options":["soon","fast","quickly","early"],"answer":3,"back":"答え：early\n訳：父は早くも朝4時には起きた。\nコツ：時刻が「早い」は early（fast は動きが速いこと）。as early as 4 ＝ 早くも4時に。\n（本冊393）"},{"id":"k394","category":"A 4択","front":"This river is （　） longer than that one.","options":["much","very","more","so"],"answer":0,"back":"答え：much\n訳：この川はあの川よりずっと長い。\nコツ：longer のような -er の形を「ずっと」と強めるのは much。very は使えない。\n（本冊394）"},{"id":"k395","type":"write","category":"C 書きかえ","front":"(a) Science is not as hard as math for me.\n(b) Science is （ ① ） （ ② ） than math for me.","answers":[["less"],["hard"]],"back":"答え：① less ② hard\n訳：私にとって理科は数学ほど難しくない。\nコツ：not as hard as（ほど難しくない）＝ less hard than。less は more の反対。\n（本冊395）"},{"id":"k396","category":"A 4択","front":"Aya is more （　） than clever.","options":["kinder","kindest","kind","the kinder"],"answer":2,"back":"答え：kind\n訳：アヤはかしこいというより、むしろやさしい。\nコツ：1人の2つの性格をくらべるときは more ＋ もとの形（kind）。kinder than にはしない。\n（本冊396）"},{"id":"k397","type":"order","category":"B 並べ替え","front":"「このスイカはあのメロンの3倍重い。」\nThis watermelon is （　　　）.","words":["three","times","heavier","than","that","melon"],"back":"答え：three times heavier than that melon（2番目 times／5番目 that）\n訳：このスイカはあのメロンの3倍重い。\nコツ：「3倍」three times を先に。そのあと heavier than（より重い）。\n（本冊397）"},{"id":"k398","category":"A 4択","front":"Yuta is （　） of the two brothers.","options":["taller","the taller","the tallest","tallest"],"answer":1,"back":"答え：the taller\n訳：ユウタは2人の兄弟のうちで背が高いほうだ。\nコツ：of the two（2人のうちで）があるときは the ＋ -er の形。2人だけなので -est は使わない。\n（本冊398）"},{"id":"k399","category":"A 4択","front":"The more you sing, （　） you will become.","options":["the better","better","the best","best"],"answer":0,"back":"答え：the better\n訳：歌えば歌うほど、うまくなる。\nコツ：「～すればするほど…」。前に The があれば、後ろにも the をつける。\n（本冊399）"},{"id":"k400","type":"order","category":"B 並べ替え","front":"「練習に時間をかければかけるほど、上手になる。」\n（　　　）, the better you will play.","words":["The","more","time","you","spend","practicing"],"back":"答え：The more time you spend practicing（2番目 more／5番目 spend）\n訳：練習に時間をかければかけるほど、上手になる。\nコツ：more time はくっつけたまま前に出す。The more time のあとに you spend practicing。\n（本冊400）"},{"id":"k401","type":"order","category":"B 並べ替え","front":"「正直なので、私はなおさら彼女が好きだ。」\nI like her （　　　）.","words":["all","the","better","for","her","honesty"],"back":"答え：all the better for her honesty（2番目 the／5番目 her）\n訳：正直なので、私はなおさら彼女が好きだ。\nコツ：all the better for ～ ＝「～なので、なおさら」。good の -er の形は better。\n（本冊401）"},{"id":"k402","type":"order","category":"B 並べ替え","front":"「彼女はお金持ちなのに、少しも幸せではない。」\nShe is （　　　）.","words":["none","the","happier","for","her","wealth"],"extra":["no"],"back":"答え：none the happier for her wealth（2番目 the／5番目 her）\n訳：彼女はお金持ちなのに、少しも幸せではない。\nコツ：none the -er の形 for ～ ＝「～なのに、少しも…ない」。the の前は no ではなく none。\n（本冊402）"}]},{"id":"ronpyo-403","group":"論理・表現 第11〜13章（12月期末）","title":"論表 比較の後半（本冊403〜430と同じ文法）","subject":"論理・表現","order":1.6,"version":2,"cards":[{"id":"k403","type":"order","category":"B 並べ替え","front":"「私はもう1か月以上ピアノを練習している。」\nI have practiced （　　　）.","words":["the","piano","for","more","than","a","month"],"back":"答え：the piano for more than a month（2番目 piano／5番目 than）\n訳：私はもう1か月以上ピアノを練習している。\nコツ：「～より多く」は more than を先に言って、そのあとに a month。\n（本冊403）"},{"id":"k404","type":"order","category":"B 並べ替え","front":"「この宿題は2時間もかからずに終わる。」\nThis homework （　　　）.","words":["takes","less","than","two","hours"],"back":"答え：takes less than two hours（2番目 less／5番目 hours）\n訳：この宿題は2時間もかからずに終わる。\nコツ：less than ＝「～より少ない」。less than を先に、そのあと two hours。\n（本冊404）"},{"id":"k405","category":"A 4択","front":"I have （　） 500 yen in my wallet, so I can't buy lunch.","options":["as many as","no more than","no more as","no many than"],"answer":1,"back":"答え：no more than\n訳：財布にはたった500円しかないので、お昼ごはんが買えない。\nコツ：no more than ＝ only（たった～しか）。お金の量に many は使わない。\n（本冊405）"},{"id":"k406","category":"A 4択","front":"(a) The bike cost as much as 50,000 yen.\n(b) The bike cost （　） 50,000 yen.","options":["no more than","not more than","no less than","at most"],"answer":2,"back":"答え：no less than\n訳：その自転車は5万円もした。\nコツ：no less than ＝ as much as（～も）。「多い！」の気持ち。no more than（たった）と反対。\n（本冊406）"},{"id":"k407","category":"A 4択","front":"A bat is （　） a bird than a cat is.","options":["any more","no more","no much","no most"],"answer":1,"back":"答え：no more\n訳：コウモリが鳥でないのは、ネコが鳥でないのと同じだ。\nコツ：no more ～ than … ＝「…と同じで～ではない」。どっちも「ちがう！」と言いたいときは no more。\n（本冊407）"},{"id":"k408","category":"A 4択","front":"My brother does not like carrots （　） I do.","options":["no more than","any more as","no longer than","any more than"],"answer":3,"back":"答え：any more than\n訳：私がニンジンを好きでないのと同じで、兄も好きではない。\nコツ：前に not があるので any more than。not ～ any more than ＝ no more ～ than。\n（本冊408）"},{"id":"k409","type":"order","category":"B 並べ替え","front":"「このパンは、あの有名な店のパンに負けないくらいおいしい。」\nThis bread is （　　　） at that famous shop.","words":["no","less","delicious","than","the","bread"],"back":"答え：no less delicious than the bread（2番目 less／5番目 the）\n訳：このパンは、あの有名な店のパンに負けないくらいおいしい。\nコツ：「負けないくらい～」は no less ～ than。no less → delicious → than の順。\n（本冊409）"},{"id":"k410","category":"A 4択","front":"The person who opened the door was （　） the famous singer.","options":["none other than","none another than","not other than","nobody more than"],"answer":0,"back":"答え：none other than\n訳：ドアを開けたのは、なんとあの有名な歌手だった。\nコツ：「なんと～その人」は none other than。この組み合わせで決まっている。\n（本冊410）"},{"id":"k411","type":"order","category":"B 並べ替え","front":"「兄はテストの前の夜にゲームをするほどばかではない。」\nMy brother （　　　） the night before a test.","words":["knows","better","than","to","play","games"],"back":"答え：knows better than to play games（2番目 better／5番目 play）\n訳：兄はテストの前の夜にゲームをするほどばかではない。\nコツ：knows better than to ～ ＝「～するほどばかではない」。knows → better → than → to の順。\n（本冊411）"},{"id":"k412","type":"order","category":"B 並べ替え","front":"「私は自転車にも乗れない。まして車の運転なんてむりだ。」\nI can't ride a bike, （　　　）.","words":["much","less","drive","a","car"],"back":"答え：much less drive a car（2番目 less／5番目 car）\n訳：私は自転車にも乗れない。まして車の運転なんてむりだ。\nコツ：前に can't（できない）があって「まして～なんて」は much less。much less を先に言う。\n（本冊412）"},{"id":"k413","type":"fix","category":"D 誤り指摘","front":"My grandma ①doesn't ②drive ③no longer, so I ④take her home.","options":["doesn't","drive","no longer","take"],"answer":2,"fix":["any longer","anymore","any more"],"back":"答え：③ no longer → any longer\n訳：祖母はもう車を運転しないので、私が家まで送る。\nコツ：doesn't にもう not が入っているので any longer。no longer なら doesn't はいらない。\n（本冊413）"},{"id":"k414","category":"A 4択","front":"This camera is superior （　） the old one.","options":["to","than","for","from"],"answer":0,"back":"答え：to\n訳：このカメラは古いカメラよりすぐれている。\nコツ：superior（すぐれている）は than ではなく to を使う。\n（本冊414）"},{"id":"k415","category":"A 4択","front":"I prefer walking （　） taking the bus.","options":["than","from","to","for"],"answer":2,"back":"答え：to\n訳：私はバスに乗るより歩くほうが好きだ。\nコツ：prefer ～ to … ＝「…より～が好き」。prefer のときは than ではなく to。\n（本冊415）"},{"id":"k416","category":"A 4択","front":"Ken is three years （　） me.","options":["older to","elder than","senior than","senior to"],"answer":3,"back":"答え：senior to\n訳：ケンは私より3歳年上だ。\nコツ：senior（年上）は to を使う。older なら than。\n（本冊416）"},{"id":"k417","category":"A 4択","front":"Takeshi is the tallest （　） the five boys.","options":["of","in","than","at"],"answer":0,"back":"答え：of\n訳：タケシは5人の男の子の中でいちばん背が高い。\nコツ：the five boys のように「なかまの数」が来たら of。「場所」なら in。\n（本冊417）"},{"id":"k418","type":"fix","category":"D 誤り指摘","front":"This ramen shop is ①too far ②the best ③in our ④town.","options":["too","the","in","town"],"answer":0,"fix":["by"],"back":"答え：① too → by\n訳：このラーメン屋は私たちの町でダントツにいちばんだ。\nコツ：「ダントツでいちばん」は by far the -est の形。too far だと「遠すぎる」になってしまう。\n（本冊418）"},{"id":"k419","type":"order","category":"B 並べ替え","front":"「これは私が今まで見た中で、まさにいちばんの映画だ。」\nThis is （　　　）.","words":["the","very","best","movie","I","have","ever","seen"],"back":"答え：the very best movie I have ever seen（2番目 very／5番目 I）\n訳：これは私が今まで見た中で、まさにいちばんの映画だ。\nコツ：「まさにいちばん」は the very best。そのあと movie I have ever seen（今まで見た中で）。\n（本冊419）"},{"id":"k420","category":"A 4択","front":"This building is the （　） in our city.","options":["second taller","tallest second","second tallest","two tallest"],"answer":2,"back":"答え：second tallest\n訳：このビルは私たちの町で2番目に高い。\nコツ：「2番目に～」は the second ＋ -est の形。second を先に言う。\n（本冊420）"},{"id":"k421","type":"fix","category":"D 誤り指摘","front":"Kyoto is ①one of the ②most ③beautiful ④city in Japan.","options":["one","most","beautiful","city"],"answer":3,"fix":["cities"],"back":"答え：④ city → cities\n訳：京都は日本でいちばん美しい町の1つだ。\nコツ：one of the ～（～のうちの1つ）は、たくさんの中から選ぶので cities と s がつく。\n（本冊421）"},{"id":"k422","category":"A 4択","front":"This is the （　） curry I've ever had.","options":["good","better","most good","best"],"answer":3,"back":"答え：best\n訳：これは今まで食べた中でいちばんおいしいカレーだ。\nコツ：the と I've ever（今までに）があれば「いちばん」。good の -est の形は best。\n（本冊422）"},{"id":"k423","type":"order","category":"B 並べ替え","front":"「こんなに大きな犬は見たことがない。」\nThis is （　　　）.","words":["the","biggest","dog","I","have","ever","seen"],"back":"答え：the biggest dog I have ever seen（2番目 biggest／5番目 have）\n訳：こんなに大きな犬は見たことがない。\nコツ：「見たことがない」でも never ではなく ever。「今まで見た中でいちばん大きい犬」と考える。\n（本冊423）"},{"id":"k424","category":"A 4択","front":"Sleep （　） eight hours a day.","options":["at last","at least","at less","in least"],"answer":1,"back":"答え：at least\n訳：少なくとも1日に8時間は寝なさい。\nコツ：「少なくとも」は at least。反対の「多くても」は at most。\n（本冊424）"},{"id":"k425","type":"order","category":"B 並べ替え","front":"「このクラスでミホほど速く走る生徒はいない。」\nNo （　　　） as fast as Miho.","words":["other","student","in","this","class","runs"],"back":"答え：other student in this class runs（2番目 student／5番目 class）\n訳：このクラスでミホほど速く走る生徒はいない。\nコツ：No other のあとは student（s がつかない1人の形）。in this class はそのすぐ後ろ。\n（本冊425）"},{"id":"k426","category":"A 4択","front":"（　） is as important as health.","options":["Not anything","Nothings","Nothing","Anything not"],"answer":2,"back":"答え：Nothing\n訳：健康ほど大切なものはない。\nコツ：「～ほど大切なものはない」は Nothing is as ～ as …。\n（本冊426）"},{"id":"k427","type":"order","category":"B 並べ替え","front":"「日本で富士山より高い山はない。」\nNo （　　　） Mt. Fuji.","words":["other","mountain","in","Japan","is","higher","than"],"back":"答え：other mountain in Japan is higher than（2番目 mountain／5番目 is）\n訳：日本で富士山より高い山はない。\nコツ：No other のあとは mountain（s がつかない1つの形）。in Japan はそのすぐ後ろ。\n（本冊427）"},{"id":"k428","type":"write","category":"C 書きかえ","front":"(a) My family is the most important thing to me.\n(b) （ ① ） （ ② ） （ ③ ） important than my family.","answers":[["Nothing","nothing"],["is"],["more"]],"back":"答え：① Nothing ② is ③ more\n訳：家族より大切なものはない。\nコツ：than があるので more。「～より大切なものはない」は Nothing is more ～ than …。\n（本冊428）"},{"id":"k429","type":"write","category":"C 書きかえ","front":"(a) An ostrich is the biggest of all birds.\n(b) An ostrich is bigger （ ① ） （ ② ） （ ③ ） bird.","answers":[["than"],["any"],["other"]],"back":"答え：① than ② any ③ other\n訳：ダチョウはほかのどの鳥よりも大きい。\nコツ：bigger than any other bird ＝「ほかのどの1羽よりも大きい」。bird に s はつけない。\n（本冊429）"},{"id":"k430","category":"A 4択","front":"I like soccer more than （　）.","options":["anything else","nothing else","else anything","anything other"],"answer":0,"back":"答え：anything else\n訳：私はほかの何よりもサッカーが好きだ。\nコツ：「ほかの何よりも」は than anything else。anything → else の順。\n（本冊430）"}]},{"id":"ronpyo-431","group":"論理・表現 第11〜13章（12月期末）","title":"論表 is か are か（本冊431〜447と同じ文法）","subject":"論理・表現","order":1.7,"version":2,"cards":[{"id":"k431a","category":"A 4択","front":"Both Ken and Yumi （　） going to play tennis tomorrow.","options":["is","are","am","be"],"answer":1,"back":"答え：are\n訳：ケンとユミは2人とも、明日テニスをする予定だ。\nコツ：both ～ and …（～も…も両方）は2人の話なので are。\n（本冊431）"},{"id":"k431b","category":"A 4択","front":"Both my sister and my brother （　） already eaten lunch.","options":["has","is","was","have"],"answer":3,"back":"答え：have\n訳：姉も兄も、もう昼ごはんを食べた。\nコツ：both ～ and … は2人の話なので、has ではなく have。\n（本冊431）"},{"id":"k432a","category":"A 4択","front":"Not only my friends but also my teacher （　） heard the news.","options":["has","have","are","is"],"answer":0,"back":"答え：has\n訳：友だちだけでなく、先生もそのニュースを聞いた。\nコツ：but also のすぐ後ろの my teacher（1人）に合わせて has。friends につられない。\n（本冊432）"},{"id":"k432b","category":"A 4択","front":"Not only Tom but also his brothers （　） good at baseball.","options":["is","am","are","has"],"answer":2,"back":"答え：are\n訳：トムだけでなく、トムのお兄さんたちも野球が上手だ。\nコツ：but also のすぐ後ろの his brothers（2人以上）に合わせて are。\n（本冊432）"},{"id":"k433a","category":"A 4択","front":"Neither Ken nor his friends （　） coming to the party.","options":["is","am","be","are"],"answer":3,"back":"答え：are\n訳：ケンも、ケンの友だちも、パーティーに来ない。\nコツ：nor のすぐ後ろの his friends（2人以上）に合わせて are。\n（本冊433）"},{"id":"k433b","category":"A 4択","front":"Neither my parents nor my brother （　） at home now.","options":["is","are","am","be"],"answer":0,"back":"答え：is\n訳：両親も兄も、今は家にいない。\nコツ：nor のすぐ後ろの my brother（1人）に合わせて is。parents につられない。\n（本冊433）"},{"id":"k434a","category":"A 4択","front":"Either she or I （　） going to clean the room.","options":["is","are","am","be"],"answer":2,"back":"答え：am\n訳：彼女か私のどちらかが、部屋をそうじする予定だ。\nコツ：or のすぐ後ろの I に合わせて am。\n（本冊434）"},{"id":"k434b","category":"A 4択","front":"Either Tom or I （　） to wash the dishes.","options":["has","have","is","having"],"answer":1,"back":"答え：have\n訳：トムか私のどちらかが、皿を洗わないといけない。\nコツ：or のすぐ後ろの I に合わせて have（I has とは言わない）。\n（本冊434）"},{"id":"k435a","type":"fix","category":"D 誤り指摘","front":"The teacher ①as well as ②you ③were ④angry.","options":["as well as","you","were","angry"],"answer":2,"fix":["was"],"back":"答え：③ were → was\n訳：あなただけでなく、先生も怒っていた。\nコツ：as well as は前に合わせる。The teacher（1人）なので was。you につられない。\n（本冊435）"},{"id":"k435b","type":"fix","category":"D 誤り指摘","front":"My brother as well as my ①parents ②are ③coming ④to dinner tonight.","options":["parents","are","coming","to dinner"],"answer":1,"fix":["is"],"back":"答え：② are → is\n訳：両親だけでなく兄も、今夜の夕食に来る。\nコツ：as well as の前の My brother（1人）に合わせて is。parents につられない。\n（本冊435）"},{"id":"k436a","category":"A 4択","front":"Most of the students in this class （　） near the school.","options":["live","lives","living","to live"],"answer":0,"back":"答え：live\n訳：このクラスの生徒のほとんどは、学校の近くに住んでいる。\nコツ：most of の後ろの students（2人以上）に合わせて、s なしの live。\n（本冊436）"},{"id":"k436b","category":"A 4択","front":"Most of the furniture in this room （　） old.","options":["are","were","is","be"],"answer":2,"back":"答え：is\n訳：この部屋の家具のほとんどは古い。\nコツ：furniture（家具）は数えられない物 → 1つあつかいで is。\n（本冊436）"},{"id":"k437a","category":"A 4択","front":"Two thirds of the cake （　） already been eaten.","options":["have","has","is","are"],"answer":1,"back":"答え：has\n訳：そのケーキの3分の2は、もう食べられてしまった。\nコツ：of の後ろの the cake（1つ）に合わせて has。\n（本冊437）"},{"id":"k437b","category":"A 4択","front":"Two thirds of the people in the town （　） cars.","options":["has","is","does","have"],"answer":3,"back":"答え：have\n訳：その町の人の3分の2は、車を持っている。\nコツ：of の後ろの the people（人たち）に合わせて have。\n（本冊437）"},{"id":"k438a","type":"fix","category":"D 誤り指摘","front":"Thirty percent of my allowance ①were ②spent ③on ④snacks.","options":["were","spent","on","snacks"],"answer":0,"fix":["was"],"back":"答え：① were → was\n訳：私のおこづかいの30パーセントは、おかしに使われた。\nコツ：of の後ろの allowance（おこづかい＝お金）は1つあつかい → was。\n（本冊438）"},{"id":"k438b","type":"fix","category":"D 誤り指摘","front":"①About 20 ②percent of the students ③in our school ④is from other cities.","options":["About","percent","in our school","is"],"answer":3,"fix":["are"],"back":"答え：④ is → are\n訳：私たちの学校の生徒の約20パーセントは、ほかの町から来ている。\nコツ：of の後ろの students（2人以上）に合わせて are。\n（本冊438）"},{"id":"k439a","category":"A 4択","front":"There （　） a lot of trees in this park.","options":["is","are","be","has"],"answer":1,"back":"答え：are\n訳：この公園には、木がたくさんある。\nコツ：There の文は後ろを見る。a lot of trees（たくさんの木）なので are。\n（本冊439）"},{"id":"k439b","category":"A 4択","front":"Since last year, there （　） many new shops in this town.","options":["has been","was","is","have been"],"answer":3,"back":"答え：have been\n訳：去年からずっと、この町には新しい店がたくさんある。\nコツ：Since（～から今まで）なので have been。shops は2つ以上なので has ではない。\n（本冊439）"},{"id":"k440a","type":"fix","category":"D 誤り指摘","front":"The ①more snow there ②are, the ③happier the children ④are.","options":["more","are","happier","are"],"answer":1,"fix":["is"],"back":"答え：② are → is\n訳：雪が多ければ多いほど、子どもたちは喜ぶ。\nコツ：snow（雪）は数えられない物 → 1つあつかいで is。最後の are は children（2人以上）なので正しい。\n（本冊440）"},{"id":"k440b","type":"fix","category":"D 誤り指摘","front":"There ①are no milk ②left ③in the ④fridge.","options":["are","left","in the","fridge"],"answer":0,"fix":["is"],"back":"答え：① are → is\n訳：冷蔵庫に牛乳が残っていない。\nコツ：milk（牛乳）は数えられない物 → 1つあつかいで is。\n（本冊440）"},{"id":"k441a","category":"A 4択","front":"The number of children who have smartphones （　） increasing.","options":["are","am","be","is"],"answer":3,"back":"答え：is\n訳：スマホを持っている子どもの数は、増えている。\nコツ：The number of ～ は「～の数」。数は1つなので is。children につられない。\n（本冊441）"},{"id":"k441b","category":"A 4択","front":"The number of people visiting this town （　） increased since last year.","options":["has","have","is","are"],"answer":0,"back":"答え：has\n訳：この町に来る人の数は、去年から増えた。\nコツ：The number of ～（～の数）は1つの話 → has。people につられない。\n（本冊441）"},{"id":"k442a","category":"A 4択","front":"A number of people （　） invited to the party.","options":["was","is","were","has"],"answer":2,"back":"答え：were\n訳：たくさんの人がそのパーティーに招待された。\nコツ：a number of ～ ＝「たくさんの～」。people（人たち）なので were。\n（本冊442）"},{"id":"k442b","category":"A 4択","front":"A number of students （　） absent today.","options":["is","are","was","has"],"answer":1,"back":"答え：are\n訳：今日はたくさんの生徒が休んでいる。\nコツ：a number of ～ ＝「たくさんの～」。students（2人以上）なので are。\n（本冊442）"},{"id":"k443a","category":"A 4択","front":"The United States （　） a big country.","options":["is","are","were","have"],"answer":0,"back":"答え：is\n訳：アメリカは大きな国だ。\nコツ：The United States（アメリカ）は s がついていても1つの国 → is。\n（本冊443）"},{"id":"k443b","category":"A 4択","front":"The United Nations （　） its main office in New York.","options":["have","is","are","has"],"answer":3,"back":"答え：has\n訳：国連の本部はニューヨークにある。\nコツ：The United Nations（国連）は s がついていても1つのグループ → has。\n（本冊443）"},{"id":"k444a","category":"A 4択","front":"Ten minutes （　） not enough time to finish my homework.","options":["are","is","have","be"],"answer":1,"back":"答え：is\n訳：10分では、宿題を終えるのに足りない。\nコツ：「10分」はひとまとまりの時間 → 1つあつかいで is。\n（本冊444）"},{"id":"k444b","category":"A 4択","front":"Twenty dollars （　） too much for this T-shirt.","options":["are","am","is","have"],"answer":2,"back":"答え：is\n訳：このTシャツに20ドルは高すぎる。\nコツ：「20ドル」はひとまとまりの金額 → 1つあつかいで is。\n（本冊444）"},{"id":"k445a","category":"A 4択","front":"The rich （　） not always happy.","options":["is","am","be","are"],"answer":3,"back":"答え：are\n訳：お金持ちの人たちが、いつも幸せとはかぎらない。\nコツ：the rich ＝ お金持ちの人たち（2人以上）→ are。\n（本冊445）"},{"id":"k445b","category":"A 4択","front":"The elderly in this town often （　） walking in the park.","options":["enjoy","enjoys","enjoying","to enjoy"],"answer":0,"back":"答え：enjoy\n訳：この町のお年寄りの人たちは、よく公園を散歩して楽しむ。\nコツ：the elderly ＝ お年寄りの人たち（2人以上）→ s なしの enjoy。\n（本冊445）"},{"id":"k446a","type":"fix","category":"D 誤り指摘","front":"The people ①who ②was hurt ③in the accident ④are now in the hospital.","options":["who","was","in","are"],"answer":1,"fix":["were"],"back":"答え：② was → were\n訳：その事故でけがをした人たちは、今、病院にいる。\nコツ：who のすぐ前の The people（人たち）に合わせて were。\n（本冊446）"},{"id":"k446b","type":"fix","category":"D 誤り指摘","front":"I ①know some boys ②who ③is good ④at soccer.","options":["know","who","is","at"],"answer":2,"fix":["are"],"back":"答え：③ is → are\n訳：私はサッカーが上手な男の子を何人か知っている。\nコツ：who のすぐ前の boys（2人以上）に合わせて are。\n（本冊446）"},{"id":"k447a","type":"fix","category":"D 誤り指摘","front":"The book ①about ②cats ③are ④on the desk.","options":["about","cats","are","on"],"answer":2,"fix":["is"],"back":"答え：③ are → is\n訳：ネコについての本は、机の上にある。\nコツ：about cats はおまけの説明。前の The book（1冊）に合わせて is。cats につられない。\n（本冊447）"},{"id":"k447b","type":"fix","category":"D 誤り指摘","front":"①This year, the price ②of ③these vegetables ④have gone up.","options":["This year","of","these vegetables","have"],"answer":3,"fix":["has"],"back":"答え：④ have → has\n訳：今年、これらの野菜のねだんが上がった。\nコツ：of these vegetables はおまけの説明。前の the price（ねだん＝1つ）に合わせて has。\n（本冊447）"}]},{"id":"ronpyo-448","group":"論理・表現 第11〜13章（12月期末）","title":"論表 質問の文（本冊448〜474と同じ文法）","subject":"論理・表現","order":1.8,"version":2,"cards":[{"id":"k448","category":"A 4択","front":"（　） did you spend your summer vacation?","options":["What","Who","How","Which"],"answer":2,"back":"答え：How\n訳：夏休みはどうやって過ごしたの？\nコツ：「どうやって」は How。spend your summer vacation で文はもうそろっているので、「何」の What は入らない。\n（本冊448）"},{"id":"k449","category":"A 4択","front":"How （　） does this bag cost?","options":["much","many","long","often"],"answer":0,"back":"答え：much\n訳：このかばんはいくらするの？\nコツ：「いくら（ねだん）」は How much。How many は「いくつ（数）」を聞くとき。\n（本冊449）"},{"id":"k450","category":"A 4択","front":"A: How （　） do you go to the gym?\nB: Two or three times a week.","options":["long","many","far","often"],"answer":3,"back":"答え：often\n訳：「どのくらいジムに行ってるの？」「週に2、3回だよ。」\nコツ：答えが「週に2、3回」。回数を聞くときは How often。\n（本冊450）"},{"id":"k451","category":"A 4択","front":"A: How （　） is it from the station to your school?\nB: About two kilometers.","options":["long","far","much","soon"],"answer":1,"back":"答え：far\n訳：「駅から学校までどのくらい遠いの？」「2キロくらいだよ。」\nコツ：答えが「2キロ」なので「遠さ」を聞く How far。How long は時間や長さ。\n（本冊451）"},{"id":"k452","type":"order","category":"B 並べ替え","front":"「家から学校まで歩いてどのくらいかかるの？」\n（　　　） from your house to school?","words":["How","long","does","it","take","you","to","walk"],"back":"答え：How long does it take you to walk\n訳：家から学校まで歩いてどのくらいかかるの？\nコツ：「どのくらい時間がかかる」は How long → does it take → you → to walk の順。\n（本冊452）"},{"id":"k453","category":"A 4択","front":"A: How （　） will the movie start?\nB: In about ten minutes.","options":["long","soon","fast","far"],"answer":1,"back":"答え：soon\n訳：「映画はあとどのくらいで始まるの？」「10分くらいでね。」\nコツ：「あとどのくらいで」は How soon。How long は「どのくらいの間」。\n（本冊453）"},{"id":"k454","category":"A 4択","front":"I wonder （　） from here to the beach.","options":["how far is it","it is how far","how is it far","how far it is"],"answer":3,"back":"答え：how far it is\n訳：ここから海までどのくらい遠いのかなあ。\nコツ：I wonder（〜かなあ）のあとに入った質問は、ふつうの文の順番（it is）にする。\n（本冊454）"},{"id":"k455","type":"order","category":"B 並べ替え","front":"「君に出会っていなかったら、ぼくの人生はどんなにちがっていただろうと、ときどき考える。」\nI sometimes think about （　　　） if I had not met you.","words":["how","different","my","life","would","have","been"],"back":"答え：how different my life would have been\n訳：君に出会っていなかったら、ぼくの人生はどんなにちがっていただろうと、ときどき考える。\nコツ：「どんなにちがう」は how different で1かたまり。そのあとは、ふつうの文の順番（my life would have been）。\n（本冊455）"},{"id":"k456","type":"order","category":"B 並べ替え","front":"「空港行きのバスがいつ出るか知ってる？」\n（　　　） for the airport?","words":["Do","you","know","when","the","bus","leaves"],"back":"答え：Do you know when the bus leaves\n訳：空港行きのバスがいつ出るか知ってる？\nコツ：Do you know のあとに入った質問は、ふつうの文の順番（the bus leaves）。\n（本冊456）"},{"id":"k457","type":"order","category":"B 並べ替え","front":"「おもちは何から作られていると思う？」\n（　　　） from?","words":["What","do","you","think","mochi","is","made"],"back":"答え：What do you think mochi is made\n訳：おもちは何から作られていると思う？\nコツ：「何だと思う？」と中身を聞くので What が一番前。do you think のあとは、ふつうの順番（mochi is）。\n（本冊457）"},{"id":"k458","category":"A 4択","front":"A: Didn't you do your homework?\nB: （　） I finished it last night.","options":["No, I did.","No, I didn't.","Yes, I didn't.","Yes, I did."],"answer":3,"back":"答え：Yes, I did.\n訳：「宿題やらなかったの？」「ううん、やったよ。昨日の夜に終わらせた。」\nコツ：日本語の「ううん」につられない。やったなら Yes, I did. やらなかったなら No, I didn't.\n（本冊458）"},{"id":"k459","category":"A 4択","front":"You aren't tired, （　）?","options":["aren't you","are you","do you","don't you"],"answer":1,"back":"答え：are you\n訳：つかれてないよね？\nコツ：文の最後の「〜ね？」は、前に not があれば not なしで聞く。aren't → are you。\n（本冊459）"},{"id":"k460","category":"A 4択","front":"What Ken said is true, （　）?","options":["isn't it","isn't he","didn't he","is it"],"answer":0,"back":"答え：isn't it\n訳：ケンが言ったことは本当だよね？\nコツ：本当なのは「ケンが言ったこと」。「こと」は it で受ける。前が is で not なしなので isn't it。\n（本冊460）"},{"id":"k461","category":"A 4択","front":"Let's have pizza for lunch, （　）?","options":["will you","don't we","shall we","do we"],"answer":2,"back":"答え：shall we\n訳：お昼はピザを食べようよ。\nコツ：Let's 〜（〜しよう）の文の最後は、いつも shall we? と決まっている。\n（本冊461）"},{"id":"k462","category":"A 4択","front":"There is a convenience store near here, （　）?","options":["isn't it","is there","doesn't it","isn't there"],"answer":3,"back":"答え：isn't there\n訳：この近くにコンビニがあるよね？\nコツ：There is 〜 の文の最後は there を使う。前が is で not なしなので isn't there。\n（本冊462）"},{"id":"k463","type":"order","category":"B 並べ替え","front":"「うちの部では、どこの出身かは大事じゃない。」\nIn our club, （　　　）.","words":["it","is","not","important","where","you","come","from"],"back":"答え：it is not important where you come from\n訳：うちの部では、どこの出身かは大事じゃない。\nコツ：「どこの出身か」は where you come from。文の途中に入った質問なので、ふつうの順番（you come）。\n（本冊463）"},{"id":"k464","type":"order","category":"B 並べ替え","front":"「この写真を見ると、昔の東京がどんなふうだったかわかる。」\nThis photo （　　　） long ago.","words":["shows","us","what","Tokyo","was","like"],"extra":["how"],"back":"答え：shows us what Tokyo was like\n訳：この写真を見ると、昔の東京がどんなふうだったかわかる。\nコツ：「どんなふう」は what 〜 like。how と like はいっしょに使わないので how がいらない。\n（本冊464）"},{"id":"k465","type":"order","category":"B 並べ替え","front":"「一人暮らしがどんな感じなのか、まったくわからなかった。」\nI had no idea （　　　） alone.","words":["what","it","would","be","like","to","live"],"extra":["was"],"back":"答え：what it would be like to live\n訳：一人暮らしがどんな感じなのか、まったくわからなかった。\nコツ：「〜するのってどんな感じ」は what it is like to 〜。would be があるので was がいらない。\n（本冊465）"},{"id":"k466","type":"order","category":"B 並べ替え","front":"「新しい先生のこと、どう思う？」\n（　　　）?","words":["What","do","you","think","of","our","new","teacher"],"extra":["how"],"back":"答え：What do you think of our new teacher\n訳：新しい先生のこと、どう思う？\nコツ：日本語は「どう思う」でも、英語は What do you think of 〜?。how がいらない。\n（本冊466）"},{"id":"k467","type":"order","category":"B 並べ替え","front":"「子どものころに乗っていた自転車は、どうなったのかなあ。」\nI wonder （　　　） I rode as a kid.","words":["what","has","become","of","the","bike"],"back":"答え：what has become of the bike\n訳：子どものころに乗っていた自転車は、どうなったのかなあ。\nコツ：「〜はどうなったか」は what has become of 〜。of とセットなのは become。\n（本冊467）"},{"id":"k468","type":"order","category":"B 並べ替え","front":"「どうしてパーティーに来なかったの？」\n（　　　） to the party?","words":["How","come","you","did","not","come"],"back":"答え：How come you did not come\n訳：どうしてパーティーに来なかったの？\nコツ：How come（どうして）のあとは、ふつうの文の順番（you did not come）。\n（本冊468）"},{"id":"k469","category":"A 4択","front":"What did you come here （　）?","options":["for","to","why","because"],"answer":0,"back":"答え：for\n訳：何をしにここへ来たの？\nコツ：What 〜 for? で「何のために」。最後の for を忘れない。\n（本冊469）"},{"id":"k470","category":"A 4択","front":"A: I have a bad headache.\nB: （　） see a doctor?","options":["Why do you","What don't you","Why don't you","How don't you"],"answer":2,"back":"答え：Why don't you\n訳：「頭がすごくいたいんだ。」「病院に行ったらどう？」\nコツ：Why don't you 〜? ＝「〜したらどう？」と相手にすすめる言い方。\n（本冊470）"},{"id":"k471","type":"order","category":"B 並べ替え","front":"「今度の土曜日、いっしょに映画を見に行かない？」\n（　　　） this Saturday?","words":["Why","don't","we","go","to","see","a","movie"],"back":"答え：Why don't we go to see a movie\n訳：今度の土曜日、いっしょに映画を見に行かない？\nコツ：Why don't we 〜? ＝「（いっしょに）〜しない？」。we なので自分も入る。Why → don't → we の順。\n（本冊471）"},{"id":"k472","category":"A 4択","front":"What about （　） the beach next Sunday?","options":["going to","go to","to go to","went to"],"answer":0,"back":"答え：going to\n訳：次の日曜日、みんなで海に行くのはどう？\nコツ：What about のあとは -ing の形（going）。How about 〜ing と同じ意味。\n（本冊472）"},{"id":"k473","type":"write","category":"C 書きかえ","front":"(a) Nobody knows what the weather will be like tomorrow.\n(b) （ ① ） knows what the weather will be like tomorrow?","answers":[["Who","who"]],"back":"答え：Who\n訳：明日の天気がどうなるかなんて、だれにもわからないよ。\nコツ：Who knows? ＝「だれが知ってる？」→「だれも知らない」。Nobody knows と同じ意味。\n（本冊473）"},{"id":"k474","type":"order","category":"B 並べ替え","front":"「今さらテストのことを心配して、何になるの？」\n（　　　） about the test now?","words":["What","is","the","use","of","worrying"],"back":"答え：What is the use of worrying\n訳：今さらテストのことを心配して、何になるの？\nコツ：What is the use of 〜ing? ＝「〜して何になるの？（何にもならない）」。of のあとは -ing の形。\n（本冊474）"}]},{"id":"ronpyo-a1","group":"論理・表現 第11〜13章（12月期末）","title":"論表 予想問題 A① 比較（4択）","subject":"論理・表現","order":2,"version":3,"cards":[{"id":"q01","category":"A 4択","front":"My brother can swim as （　） as I can.","options":["faster","fast","fastest","more fast"],"answer":1,"back":"答え：fast\n訳：兄はぼくと同じくらい速く泳げる。\nコツ：as と as にはさまれたら、もとの形（-er や -est がつかない形）。\n（本冊374〜375）"},{"id":"q02","category":"A 4択","front":"This bag is not as heavy （　） it looks.","options":["than","so","that","as"],"answer":3,"back":"答え：as\n訳：このかばんは、見た目ほど重くない。\nコツ：前に as があるので、後ろも as。as 〜 as はペア。\n（本冊376）"},{"id":"q03","category":"A 4択","front":"Our new gym is three times （　） the old one.","options":["as large as","larger as","as larger than","large as"],"answer":0,"back":"答え：as large as\n訳：新しい体育館は、前の体育館の3倍の広さだ。\nコツ：three times（3倍）のあとは as 〜 as の形。まん中はもとの形（-er がつかない）。\n（本冊378〜381）"},{"id":"q04","category":"A 4択","front":"This tablet is half （　） of that laptop.","options":["as weight","weight as","the weight","the heavy"],"answer":2,"back":"答え：the weight\n訳：このタブレットは、あのノートパソコンの半分の重さだ。\nコツ：half（半分）のあと、後ろに of があるので the weight（重さ）。\n（本冊382〜383）"},{"id":"q05","category":"A 4択","front":"Please answer the email as soon as （　）.","options":["possible","you possible","possibly","can"],"answer":0,"back":"答え：possible\n訳：できるだけ早く、メールに返事してね。\nコツ：as soon as possible ＝「できるだけ早く」。セットで覚える。\n（本冊384〜385）"},{"id":"q06","category":"A 4択","front":"She left without so much as （　） goodbye.","options":["said","saying","say","to say"],"answer":1,"back":"答え：saying\n訳：彼女は、さよならさえ言わずに出ていった。\nコツ：without（〜しないで）のあとは -ing の形。so much as は「〜さえ」。\n（本冊388）"},{"id":"q07","category":"A 4択","front":"As （　） as 300 people came to the small concert.","options":["much","most","more","many"],"answer":3,"back":"答え：many\n訳：その小さなコンサートに、300人もの人が来た。\nコツ：people（人）は数えられるので many。as many as 300 ＝「300人も」。\n（本冊391）"},{"id":"q08","category":"A 4択","front":"It's a real bargain! You can buy this shirt for as （　） as five dollars.","options":["many","much","little","less"],"answer":2,"back":"答え：little\n訳：このシャツは、たった5ドルで買える。\nコツ：five dollars は「金額」＝量なので little。as little as ＝「たった〜」。\n（本冊392）"},{"id":"q09","category":"A 4択","front":"This movie is （　） more exciting than the first one.","options":["very","much","so","too"],"answer":1,"back":"答え：much\n訳：この映画は、1作目よりずっとおもしろい。\nコツ：more 〜 than（〜より）を「ずっと」と強めるのは much。very は使えない。\n（本冊394）"},{"id":"q10","category":"A 4択","front":"Ken is the taller （　） the two boys.","options":["of","in","among","than"],"answer":0,"back":"答え：of\n訳：ケンは、2人の男の子のうち背が高いほうだ。\nコツ：the two（2人）があったら of。「2人のうちの」＝ of the two。\n（本冊398）"},{"id":"q11","category":"A 4択","front":"The （　） you practice, the better you will play.","options":["much","most","more","many"],"answer":2,"back":"答え：more\n訳：練習すればするほど、うまくなるよ。\nコツ：後ろが the better（-er の形）なので、前も the more。The -er, the -er で「〜ほど〜」。\n（本冊399〜400）"},{"id":"q12","category":"A 4択","front":"I like him all the （　） for his honesty.","options":["best","good","well","better"],"answer":3,"back":"答え：better\n訳：正直だから、私は彼がなおさら好きだ。\nコツ：all the のあとは -er の形（better）。for 〜 で「〜だから、なおさら」。\n（本冊401）"},{"id":"q13","category":"A 4択","front":"The station was really close. It took me no （　） than ten minutes to walk there.","options":["less","much","most","more"],"answer":3,"back":"答え：more\n訳：そこまで歩くのに、たった10分しかかからなかった。\nコツ：no more than ＝「たった〜」（少ない）。no less than は「〜も」（多い）。\n（本冊405〜406）"},{"id":"q14","category":"A 4択","front":"A bat is no more a bird （　） a whale is a fish.","options":["than","that","as","so"],"answer":0,"back":"答え：than\n訳：コウモリが鳥でないのは、クジラが魚でないのと同じだ。\nコツ：前に more があるので、ペアは than。\n（本冊407〜408）"},{"id":"q15","category":"A 4択","front":"He knows （　） than to believe such a story.","options":["well","better","good","best"],"answer":1,"back":"答え：better\n訳：彼は、そんな話を信じるほどバカじゃない。\nコツ：後ろに than があるので -er の形の better。know better than to 〜 ＝「〜するほどバカじゃない」。\n（本冊411）"},{"id":"q16","category":"A 4択","front":"She can't speak French, （　） Russian.","options":["much more","no less","much less","any more"],"answer":2,"back":"答え：much less\n訳：彼女はフランス語が話せない。ましてロシア語なんて無理だ。\nコツ：前が can't（〜ない）の文なので much less ＝「まして〜ない」。\n（本冊412）"},{"id":"q17","category":"A 4択","front":"This new model is superior （　） the old one.","options":["to","of","than","for"],"answer":0,"back":"答え：to\n訳：この新しい機種は、古いのよりすぐれている。\nコツ：superior（すぐれている）は than ではなく to を使う。\n（本冊414・416）"},{"id":"q18","category":"A 4択","front":"I prefer walking （　） taking the bus.","options":["than","with","to","for"],"answer":2,"back":"答え：to\n訳：バスに乗るより、歩くほうが好きだ。\nコツ：prefer A to B ＝「BよりAが好き」。prefer は than ではなく to。\n（本冊415）"},{"id":"q19","category":"A 4択","front":"Mt. Everest is the highest mountain （　） the world.","options":["of","in","at","among"],"answer":1,"back":"答え：in\n訳：エベレストは世界でいちばん高い山だ。\nコツ：the world（世界）のような「場所」の中でいちばんなら in。\n（本冊417・420）"},{"id":"q20","category":"A 4択","front":"This is （　） the best pizza I have ever eaten.","options":["very","more","so","by far"],"answer":3,"back":"答え：by far\n訳：これは、今まで食べた中でダントツにおいしいピザだ。\nコツ：the best（いちばん）を「ダントツで」と強めるのは by far。very は the の前に置けない。\n（本冊418〜419）"},{"id":"q21","category":"A 4択","front":"Tokyo is one of the largest （　） in the world.","options":["city","a city","cities","the city"],"answer":2,"back":"答え：cities\n訳：東京は、世界でいちばん大きい都市の1つだ。\nコツ：one of the 〜（〜のうちの1つ）のあとは -s がついた形。city → cities。\n（本冊421）"},{"id":"q22","category":"A 4択","front":"No other student in her class is （　） than Yumi.","options":["taller","tall","tallest","as tall"],"answer":0,"back":"答え：taller\n訳：クラスで、ユミより背の高い生徒はほかにいない。\nコツ：後ろに than があるので -er の形の taller。\n（本冊425〜427）"},{"id":"q23","category":"A 4択","front":"Time is more precious than anything （　）.","options":["other","more","any","else"],"answer":3,"back":"答え：else\n訳：時間は、ほかのどんなものより大切だ。\nコツ：anything に「ほかの」をつけるなら後ろに else。anything else ＝「ほかの何か」。\n（本冊430）"},{"id":"q24","category":"A 4択","front":"Lake Biwa is larger than any other （　） in Japan.","options":["lakes","lake","the lake","a lake"],"answer":1,"back":"答え：lake\n訳：琵琶湖は、日本のほかのどの湖よりも大きい。\nコツ：any other（ほかのどの）のあとは -s をつけない形。lake のまま。\n（本冊429）"}]},{"id":"ronpyo-a2","group":"論理・表現 第11〜13章（12月期末）","title":"論表 予想問題 A② 一致・疑問文（4択）","subject":"論理・表現","order":3,"version":3,"cards":[{"id":"q01","category":"A 4択","front":"Both my father and my mother （　） teachers.","options":["is","are","has","was"],"answer":1,"back":"答え：are\n訳：父も母も先生だ。\nコツ：Both（2人とも）で父と母の2人。2人以上なら are。\n（本冊431）"},{"id":"q02","category":"A 4択","front":"Not only the students but also their teacher （　） excited.","options":["were","have been","are","was"],"answer":3,"back":"答え：was\n訳：生徒たちだけでなく、先生もわくわくしていた。\nコツ：but also のすぐ後ろ（their teacher＝1人）に合わせる。1人で昔のことなので was。\n（本冊432）"},{"id":"q03","category":"A 4択","front":"Either you or Tom （　） to clean the room.","options":["have","are","has","were"],"answer":2,"back":"答え：has\n訳：君かトムのどちらかが、部屋をそうじしないといけない。\nコツ：or のすぐ後ろの Tom（1人）に合わせて has。\n（本冊433〜434）"},{"id":"q04","category":"A 4択","front":"My sister, as well as her friends, （　） going to the festival.","options":["are","is","were","have"],"answer":1,"back":"答え：is\n訳：友だちだけでなく、姉もお祭りに行く予定だ。\nコツ：as well as 〜 はおまけ。文のはじめの My sister（1人）に合わせて is。\n（本冊435）"},{"id":"q05","category":"A 4択","front":"Most of the water in this river （　） polluted.","options":["is","were","are","have been"],"answer":0,"back":"答え：is\n訳：この川の水のほとんどは、よごれている。\nコツ：of のあとの water（水）は数えられない物なので is。\n（本冊436）"},{"id":"q06","category":"A 4択","front":"Two thirds of the students （　） against the plan.","options":["was","is","were","has"],"answer":2,"back":"答え：were\n訳：生徒の3分の2が、その計画に反対だった。\nコツ：of のあとの students（生徒たち＝2人以上）に合わせる。2人以上で昔のことなので were。\n（本冊437〜438）"},{"id":"q07","category":"A 4択","front":"There （　） a lot of chairs in the hall.","options":["is","was","has","are"],"answer":3,"back":"答え：are\n訳：ホールには、いすがたくさんある。\nコツ：There のあとは、後ろの chairs（いすがたくさん）に合わせて are。\n（本冊439〜440）"},{"id":"q08","category":"A 4択","front":"The number of tourists （　） increasing every year.","options":["are","have","were","is"],"answer":3,"back":"答え：is\n訳：観光客の数は、毎年ふえている。\nコツ：The number of 〜 ＝「〜の数」。数は1つなので is。\n（本冊441）"},{"id":"q09","category":"A 4択","front":"A number of books （　） stolen from the library.","options":["were","was","has","is"],"answer":0,"back":"答え：were\n訳：図書館から、たくさんの本がぬすまれた。\nコツ：A number of 〜 ＝「たくさんの〜」。本がたくさん（2つ以上）なので were。\n（本冊442）"},{"id":"q10","category":"A 4択","front":"Ten kilometers （　） a long way to walk.","options":["are","is","were","have"],"answer":1,"back":"答え：is\n訳：10キロは、歩くには長い道のりだ。\nコツ：10キロ・3時間・100円のような「きょり・時間・お金」は1つのかたまりなので is。\n（本冊444）"},{"id":"q11","category":"A 4択","front":"The young （　） often interested in new technology.","options":["is","was","are","has"],"answer":2,"back":"答え：are\n訳：若い人たちは、新しい技術に興味をもつことが多い。\nコツ：The young ＝ young people（若い人たち）。2人以上なので are。\n（本冊445）"},{"id":"q12","category":"A 4択","front":"A: （　） do you go to the dentist?\nB: Twice a year.","options":["How often","How long","How far","How soon"],"answer":0,"back":"答え：How often\n訳：どのくらいよく歯医者に行くの？ — 年に2回だよ。\nコツ：答えが Twice（2回）＝回数なので How often。\n（本冊450）"},{"id":"q13","category":"A 4択","front":"A: （　） is it from your house to the station?\nB: About two kilometers.","options":["How long","How much","How far","How often"],"answer":2,"back":"答え：How far\n訳：家から駅まで、どのくらいの距離？ — 2キロくらい。\nコツ：答えが two kilometers（きょり）なので How far。\n（本冊451）"},{"id":"q14","category":"A 4択","front":"I wonder （　）.","options":["where does she live","where she lives","she lives where","does she live where"],"answer":1,"back":"答え：where she lives\n訳：彼女はどこに住んでいるのかなあ。\nコツ：I wonder のあとは where のあとにふつうの文（she lives）。does は使わない。\n（本冊454）"},{"id":"q15","category":"A 4択","front":"（　） do you think will win the game?","options":["Whose","Do you know who","Whom","Who"],"answer":3,"back":"答え：Who\n訳：だれが試合に勝つと思う？\nコツ：「だれが」とたずねるので Who。Who を文のいちばん前に出す。\n（本冊457）"},{"id":"q16","category":"A 4択","front":"A: Don't you like coffee?\nB: （　） I don't drink it at all.","options":["Yes, I do.","Yes, I don't.","No, I don't.","No, I do."],"answer":2,"back":"答え：No, I don't.\n訳：コーヒー好きじゃないの？ — うん、好きじゃない。全然飲まないよ。\nコツ：好きじゃない（don't）なら英語は No。日本語の「うん」につられない。\n（本冊458）"},{"id":"q17","category":"A 4択","front":"You haven't finished your homework, （　）?","options":["have you","did you","haven't you","do you"],"answer":0,"back":"答え：have you\n訳：宿題、まだ終わってないよね？\nコツ：前が haven't（〜ない）なので、後ろは n't をとって have you。\n（本冊459）"},{"id":"q18","category":"A 4択","front":"Let's take a break, （　）?","options":["will you","don't we","won't you","shall we"],"answer":3,"back":"答え：shall we\n訳：ちょっと休もうよ、ね？\nコツ：Let's（〜しよう）の文の「ね？」は shall we と決まっている。\n（本冊461）"},{"id":"q19","category":"A 4択","front":"（　） don't you ask your teacher for advice?","options":["What","Why","How","Where"],"answer":1,"back":"答え：Why\n訳：先生にアドバイスをもらったら？\nコツ：Why don't you 〜? ＝「〜したらどう？」。セットで覚える。\n（本冊470）"},{"id":"q20","category":"A 4択","front":"A: What is the new teacher （　）?\nB: She is kind and funny.","options":["as","like","about","for"],"answer":1,"back":"答え：like\n訳：新しい先生って、どんな人？ — やさしくておもしろいよ。\nコツ：What is 〜 like? ＝「〜はどんな人（物）？」。最後の like がポイント。\n（本冊464）"},{"id":"q21","category":"A 4択","front":"What did you go to the city （　）?","options":["of","to","than","for"],"answer":3,"back":"答え：for\n訳：何のために街へ行ったの？\nコツ：What 〜 for? ＝「何のために？」。最後の for がポイント。\n（本冊469）"},{"id":"q22","category":"A 4択","front":"（　） come you were late this morning?","options":["How","Why","What","Where"],"answer":0,"back":"答え：How\n訳：どうして今朝おくれたの？\nコツ：How come 〜? ＝「どうして〜？」。come とセットなのは How。\n（本冊468）"},{"id":"q23","category":"A 4択","front":"A: Will our team win the final next week?\nB: （　） knows what will happen. Let's just wait and see.","options":["Everybody","Somebody","Nobody","Anybody"],"answer":2,"back":"答え：Nobody\n訳：何が起こるかなんて、だれにもわからない。\nコツ：「だれにも〜ない」＝ Nobody。Who knows?（だれが知ってる？＝だれも知らない）も同じ意味。\n（本冊473）"}]},{"id":"ronpyo-b","group":"論理・表現 第11〜13章（12月期末）","title":"論表 予想問題 B 並べ替え","subject":"論理・表現","order":4,"version":4,"cards":[{"id":"q01","type":"order","category":"B 並べ替え","front":"「この教室はあの教室の2倍の広さがある。」\nThis classroom is （　　　）.","words":["twice","as","large","as","that","one"],"back":"答え：twice as large as that one（2番目 as／5番目 that）\n訳：この教室はあの教室の2倍の広さがある。\nコツ：「2倍」twice を一番前に。そのあと as large as。"},{"id":"q02","type":"order","category":"B 並べ替え","front":"「私は彼ほど多くのCDを持っていない。」\nI don't have （　　　）.","words":["as","many","CDs","as","he","does"],"back":"答え：as many CDs as he does（2番目 many／5番目 he）\n訳：私は彼ほど多くのCDを持っていない。\nコツ：many CDs はくっつけたまま、as と as ではさむ。\n（本冊377）"},{"id":"q03","type":"order","category":"B 並べ替え","front":"「宿題を早く始めれば始めるほど、早く終わる。」\n（　　　）, the sooner you will finish.","words":["The","sooner","you","start","your","homework"],"back":"答え：The sooner you start your homework（2番目 sooner／5番目 your）\n訳：宿題を早く始めれば始めるほど、早く終わる。\nコツ：The sooner を先頭に。そのあと you start（だれが → する）。"},{"id":"q04","type":"order","category":"B 並べ替え","front":"「彼はまちがいもするけれど、それでも私は彼を尊敬している。」\nI （　　　） his mistakes.","words":["respect","him","none","the","less","for"],"back":"答え：respect him none the less for（2番目 him／5番目 less）\n訳：彼はまちがいもするけれど、それでも私は彼を尊敬している。\nコツ：none the less for ～ ＝「～があっても、それでも」。none → the → less → for の順。\n（本冊402）"},{"id":"q05","type":"order","category":"B 並べ替え","front":"「ケンはお兄さんに負けないくらい頭がいい。」\nKen is （　　　）.","words":["no","less","clever","than","his","brother"],"back":"答え：no less clever than his brother（2番目 less／5番目 his）\n訳：ケンはお兄さんに負けないくらい頭がいい。\nコツ：no less ～ than ＝「～に負けないくらい」。no less → clever → than の順。\n（本冊409）"},{"id":"q06","type":"order","category":"B 並べ替え","front":"「このクラスでリナほど速く泳ぐ生徒はいない。」\n（　　　） swims as fast as Rina.","words":["No","other","student","in","this","class"],"back":"答え：No other student in this class（2番目 other／5番目 this）\n訳：このクラスでリナほど速く泳ぐ生徒はいない。\nコツ：「ほかのどの生徒も～ない」は No other student。すぐ後ろに in this class。\n（本冊425）"},{"id":"q07","type":"order","category":"B 並べ替え","front":"「これは私が今まで見た中で一番わくわくする映画です。」\nThis is （　　　） ever seen.","words":["the","most","exciting","movie","I","have"],"back":"答え：the most exciting movie I have（2番目 most／5番目 I）\n訳：これは私が今まで見た中で一番わくわくする映画です。\nコツ：「いちばん～な」は the most ～。movie のすぐ後ろに I have（私が～した）。\n（本冊422〜423）"},{"id":"q08","type":"order","category":"B 並べ替え","front":"「学校までどれくらい時間がかかるか知っていますか。」\nDo you know （　　　） to school?","words":["how","long","it","takes","to","get"],"back":"答え：how long it takes to get（2番目 long／5番目 to）\n訳：学校までどれくらい時間がかかるか知っていますか。\nコツ：Do you know のあとは、ふつうの文の順番（it takes）。takes it にはしない。\n（本冊452・456）"},{"id":"q09","type":"order","category":"B 並べ替え","front":"「彼女はなぜ怒ったと思いますか。」\nWhy （　　　）?","words":["do","you","think","she","was","angry"],"back":"答え：do you think she was angry（2番目 you／5番目 was）\n訳：彼女はなぜ怒ったと思いますか。\nコツ：Why のすぐ後ろに do you think。そのあと she was angry。\n（本冊457）"},{"id":"q10","type":"order","category":"B 並べ替え","front":"「その映画についてどう思いますか。」\n（　　　） the movie?","words":["What","do","you","think","of"],"back":"答え：What do you think of（2番目 do／5番目 of）\n訳：その映画についてどう思いますか。\nコツ：「どう思う？」は What do you think of ～? 「どう」につられて How にしない。\n（本冊466）"},{"id":"q11","type":"order","category":"B 並べ替え","front":"「そんなことで泣いて、何の役に立つの？」\nWhat （　　　） it?","words":["is","the","use","of","crying","about"],"back":"答え：is the use of crying about（2番目 the／5番目 crying）\n訳：そんなことで泣いて、何の役に立つの？\nコツ：What is the use of ～ing? ＝「～して何の役に立つの？（立たない）」。\n（本冊474）"}]},{"id":"ronpyo-cd","group":"論理・表現 第11〜13章（12月期末）","title":"論表 予想問題 C・D 書きかえ・誤り指摘","subject":"論理・表現","order":5,"version":4,"cards":[{"id":"q01","type":"write","category":"C 書きかえ","front":"(a) This watch is not as expensive as that one.\n(b) This watch is （ ① ）（ ② ） than that one.","answers":[["less"],["expensive"]],"back":"答え：① less　② expensive\n訳：この時計は、あの時計ほど高くない。\nコツ：not as ～ as（ほど～ない）＝ less ～ than。less は more の反対。\n（本冊395）"},{"id":"q02","type":"write","category":"C 書きかえ","front":"(a) Lake Biwa is the largest lake in Japan.\n(b) Lake Biwa is larger than （ ① ）（ ② ） lake in Japan.","answers":[["any"],["other"]],"back":"答え：① any　② other\n訳：琵琶湖は、日本でいちばん大きい湖だ。\nコツ：「一番大きい」＝「ほかのどの湖よりも大きい」。ほかのどの ＝ any other。\n（本冊429）"},{"id":"q03","type":"write","category":"C 書きかえ","front":"(a) I have only 300 yen.\n(b) I have no （ ① ）（ ② ） 300 yen.","answers":[["more"],["than"]],"back":"答え：① more　② than\n訳：私は300円しか持っていない。\nコツ：no more than ～ ＝「～しか（ない）」＝ only。\n（本冊405）"},{"id":"q04","type":"write","category":"C 書きかえ","front":"(a) Mr. Sato is a scientist rather than a doctor.\n(b) Mr. Sato is not （ ① ）（ ② ） a doctor （ ③ ） a scientist.","answers":[["so"],["much"],["as"]],"back":"答え：① so　② much　③ as\n訳：佐藤さんは、医者というより、むしろ科学者だ。\nコツ：not so much A as B ＝「AというよりむしろB」。much の相手は as。\n（本冊386）"},{"id":"q05","type":"write","category":"C 書きかえ","front":"(a) Nobody knows what will happen tomorrow.\n(b) （ ① ）（ ② ） what will happen tomorrow?","answers":[["Who"],["knows"]],"back":"答え：① Who　② knows\n訳：あした何が起こるかは、だれにもわからない。\nコツ：「だれが知っているだろう？」＝「だれも知らない」。最後の ? がヒント。knows の s をわすれない。\n（本冊473）"},{"id":"q06","type":"write","category":"C 書きかえ","front":"(a) Why don't we play soccer?\n(b) （ ① ） play soccer, （ ② ）（ ③ ）?","answers":[["Let's"],["shall"],["we"]],"back":"答え：① Let's　② shall　③ we\n訳：サッカーをしようよ。\nコツ：Why don't we ～? ＝「～しようよ」＝ Let's ～。Let's の文の「ね？」は shall we。\n（本冊471）"},{"id":"q07","type":"write","category":"C 書きかえ","front":"(a) It is no use worrying about the test.\n(b) What is the （ ① ）（ ② ） worrying about the test?","answers":[["use"],["of"]],"back":"答え：① use　② of\n訳：テストのことを心配しても、むだだ。\nコツ：It is no use ～ing（～してもむだ）＝ What is the use of ～ing?（～して何になるの？）\n（本冊474）"},{"id":"q08","type":"fix","category":"D 誤り指摘","front":"The number of ①students ②in this school ③have ④increased.","options":["students","in this school","have","increased"],"answer":2,"fix":["has"],"back":"答え：③ have → has\n訳：この学校の生徒の数は、ふえた。\nコツ：the number of ～ は「～の数」。数は1つなので has。\n（本冊441）"},{"id":"q09","type":"fix","category":"D 誤り指摘","front":"My mother, ①as well as ②my sisters, ③like ④watching movies.","options":["as well as","my sisters","like","watching movies"],"answer":2,"fix":["likes"],"back":"答え：③ like → likes\n訳：姉妹たちと同じように、母も映画を見るのが好きだ。\nコツ：as well as ～ の文は、前の My mother が中心。お母さんは1人 → likes。\n（本冊435）"},{"id":"q10","type":"fix","category":"D 誤り指摘","front":"This is ①one of ②the oldest ③temple ④in Kyoto.","options":["one of","the oldest","temple","in Kyoto"],"answer":2,"fix":["temples"],"back":"答え：③ temple → temples\n訳：これは、京都でいちばん古いお寺の1つだ。\nコツ：one of（～のうちの1つ）は、たくさんある中の1つ → temples と s がつく。\n（本冊421）"},{"id":"q11","type":"fix","category":"D 誤り指摘","front":"A: How ①long is it ②from your house ③to the station?\nB: ④About two kilometers.","options":["long","from your house","to the station","About two kilometers"],"answer":0,"fix":["far"],"back":"答え：① long → far\n訳：家から駅まで、どのくらいの距離？ — 2キロくらい。\nコツ：答えが「約2キロ」＝ 道のりの長さ。「どれくらい遠い？」は How far。\n（本冊451）"},{"id":"q12","type":"fix","category":"D 誤り指摘","front":"This bag is ①very ②lighter ③than ④mine.","options":["very","lighter","than","mine"],"answer":0,"fix":["much","far","a lot","even","still"],"back":"答え：① very → much\n訳：このかばんは、私のよりずっと軽い。\nコツ：lighter のような -er の形を強めるのは much。very は使えない。\n（本冊394）"},{"id":"q13","type":"fix","category":"D 誤り指摘","front":"There ①are ②a lot of water ③in ④this bottle.","options":["are","a lot of water","in","this bottle"],"answer":0,"fix":["is"],"back":"答え：① are → is\n訳：このびんには、水がたくさん入っている。\nコツ：water は数えられない物 → is。a lot of がついても is のまま。\n（本冊440）"},{"id":"q14","type":"fix","category":"D 誤り指摘","front":"I ①prefer ②tea ③than ④coffee.","options":["prefer","tea","than","coffee"],"answer":2,"fix":["to"],"back":"答え：③ than → to\n訳：私は、コーヒーより紅茶が好きだ。\nコツ：prefer は than ではなく to を使う。prefer tea to coffee ＝ コーヒーより紅茶が好き。\n（本冊415）"}]}];
